// Métricas de diseño oficiales (para el cuadro de Simbología de Diseño)
export const getTroncalDesignMetrics = (extraRoutes: FiberRoute[] = [], extraMufas: EmpalmeClosure[] = []) => {
  const allRoutes = [...troncalIxtJocRoutes, ...extraRoutes];
  const allMufas = [...troncalMufas, ...extraMufas];
  
  let dist12hDistribucionMl = 0;
  let dist12hTroncalMl = 0;
  let dist48hTroncalMl = 0;
  let dist96hTroncalMl = 0;
  let dist24hTroncalMl = 0;
  let totalKm = 0;

  for (const r of allRoutes) {
    const ml = r.distancia_metros || 0;
    totalKm += (r.distancia_km || ml / 1000.0);
    
    if (r.subtipo === '12_distribucion' || (r.hilos === 12 && r.tipo === 'ramal')) {
      dist12hDistribucionMl += ml;
    } else if (r.subtipo === '12_troncal' || (r.hilos === 12 && r.tipo === 'troncal')) {
      dist12hTroncalMl += ml;
    } else if (r.subtipo === '48_troncal' || r.hilos === 48) {
      dist48hTroncalMl += ml;
    } else if (r.subtipo === '96_troncal' || r.hilos === 96) {
      dist96hTroncalMl += ml;
    } else {
      dist24hTroncalMl += ml;
    }
  }

  return {
    fibra12hDistribucionMl: Math.round(dist12hDistribucionMl),
    fibra12hTroncalMl: Math.round(dist12hTroncalMl),
    fibra48hTroncalMl: Math.round(dist48hTroncalMl),
    fibra96hTroncalMl: Math.round(dist96hTroncalMl),
    fibra24hTroncalMl: Math.round(dist24hTroncalMl),
    totalLineasKm: Number(totalKm.toFixed(2)),
    totalRutasCount: allRoutes.length,
    totalMufasCount: allMufas.length,
    totalGasasCount: troncalGasas.length,
    totalPostesCfeCount: troncalPostesCfe.length,
    totalPostesPropuestosCount: troncalPostesPropuestos.length
  };
};
